const staticData = $getWorkflowStaticData('node');
const response = $input.first().json;
const orders = response.data?.orders || [];

const lastSeenTime = staticData.lastOrderTime ? new Date(staticData.lastOrderTime) : new Date(0);
const newOrders = [];

for (const order of orders) {
  const createdAt = new Date(order.createdAt);
  if (createdAt > lastSeenTime) {
    newOrders.push(order);
  }
}

if (orders.length > 0) {
  const latestTime = new Date(orders[0].createdAt);
  if (latestTime > lastSeenTime) {
    staticData.lastOrderTime = latestTime.toISOString();
  }
}

return newOrders.map(order => {
  const itemsHtml = (order.items || []).map(item => {
    const size = item.variant?.Size ? ` (Size: ${item.variant.Size})` : '';
    return `<li>${item.name}${size} — Qty: ${item.quantity} × ৳${item.price} = ৳${item.total}</li>`;
  }).join('');

  return {
    json: {
      ...order,
      orderNumberDisplay: order.displayOrderNumber || order.orderNumber,
      customerName: order.customerInfo?.name || order.guestInfo?.name || 'N/A',
      customerPhone: order.customerInfo?.phone || order.guestInfo?.phone || 'N/A',
      totalAmount: order.pricing?.total ?? order.orderSummary?.total ?? 0,
      fullAddress: order.shippingAddress
        ? `${order.shippingAddress.address}, ${order.shippingAddress.area}, ${order.shippingAddress.city}`
        : 'N/A',
      itemsHtml
    }
  };
});

const response = $input.first().json;
const orders = response.data?.orders || [];

const today = new Date().toDateString();
const todaysOrders = orders.filter(o => new Date(o.createdAt).toDateString() === today);

let totalSales = 0;
const statusCounts = {};

for (const order of todaysOrders) {
  const amount = order.pricing?.total ?? order.orderSummary?.total ?? 0;
  totalSales += amount;
  const status = order.orderStatus || 'unknown';
  statusCounts[status] = (statusCounts[status] || 0) + 1;
}

const statusRows = Object.entries(statusCounts)
  .map(([status, count]) => `<li>${status}: ${count}</li>`)
  .join('');

const summaryHtml = `
<h2>Store - Daily Sales Summary</h2>
<p><b>Date:</b> ${new Date().toLocaleDateString()}</p>
<p><b>Total Orders Today:</b> ${todaysOrders.length}</p>
<p><b>Total Sales:</b> ৳${totalSales.toFixed(2)}</p>
<h3>Status Breakdown:</h3>
<ul>${statusRows}</ul>
`;

return [{ json: { totalOrders: todaysOrders.length, totalSales, statusCounts, summaryHtml } }];

const order = $input.first().json;

const items = (order.items || []).map(item => ({
  name: item.name + (item.variant?.Size ? ` (Size: ${item.variant.Size})` : ''),
  quantity: item.quantity,
  unit_cost: item.price
}));

const invoicePayload = {
  from: "Store Name",
  to: `${order.customerName}\n${order.customerPhone}\n${order.fullAddress}`,
  number: order.orderNumberDisplay,
  date: new Date(order.createdAt).toISOString().split('T')[0],
  currency: "BDT",
  items,
  shipping: order.pricing?.shipping || 0,
  notes: "Thank you for your order!",
  terms: `Payment Method: ${order.paymentMethod} | Payment Status: ${order.paymentStatus}`
};

return [{
  json: {
    ...order,
    invoicePayload
  }
}];
